export class Ledger {
  #entries: Entry[] = [];
  #chain: Promise<unknown> = Promise.resolve();

  #serial<T>(op: () => T): Promise<T> {
    const run = this.#chain.then(op, op);
    this.#chain = run.catch(() => {});   // queue survives rejections
    return run;
  }
  post(e: Entry): Promise<number> { return this.#serial(() => this.#entries.push(e)); }
  snapshot(): Promise<readonly Entry[]> { return this.#serial(() => [...this.#entries]); }
}
